import numpy as np
from rcb_client import Robot
s=Robot().spec()
for cam in ['right','left']:
 T=np.array(s['cameras'][cam]['cam2world_gl']);K=np.array(s['cameras'][cam]['intrinsic_cv']);
 print(cam)
 for p in [(.015,.13,.99),(.015,.16,1.0),(.015,.22,1.0),(-.025,.13,.99),(.055,.13,.99)]:
  v=T[:3,:3].T@(np.array(p)-T[:3,3]);pix=K@np.array([v[0]/-v[2],-v[1]/-v[2],1]);print(p,np.round(pix[:2],1))
